#!/usr/bin/env Rscript
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");`%||%`<-function(x,y)if(is.null(x)||!length(x))y else x;source(file.path(root,"app/shiny/R/job_manager.R"))
metadata<-list(selected_comparisons=unname(c("a","b")),summary=list(completed=4L,failed=0L),nested=list(mode="preview"));safe<-json_safe_value(metadata);warnings<-character();json<-withCallingHandlers(jsonlite::toJSON(safe,auto_unbox=TRUE),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});stopifnot(is.list(safe$summary),is.null(names(safe$selected_comparisons)),!length(warnings),grepl('"selected_comparisons":["a","b"]',json,fixed=TRUE),grepl('"completed":4',json,fixed=TRUE));cat("PASS\n")
